with expanded as (
  select skill_code, syllable_count, unnest(items) as word
  from book_vocabulary_source
), unique_words as (
  select word, min(syllable_count) as syllable_count
  from expanded
  group by word
)
insert into public.words (
  display_text,
  normalized_text,
  syllable_count,
  difficulty,
  source_note
)
select
  word,
  word,
  syllable_count,
  case when syllable_count = 1 then 1 else 2 end,
  'แบบฝึกอ่านจากหนังสือแบบเรียนเร็วใหม่ เล่ม ๑ ตอนต้นและตอนกลาง'
from unique_words source
where not exists (
  select 1 from public.words existing where existing.normalized_text = source.word
);

with expanded as (
  select skill_code, syllable_count, unnest(items) as word
  from book_vocabulary_source
), unique_words as (
  select word, min(syllable_count) as syllable_count
  from expanded
  group by word
)
update public.words word
set
  syllable_count = source.syllable_count,
  source_note = 'แบบฝึกอ่านจากหนังสือแบบเรียนเร็วใหม่ เล่ม ๑ ตอนต้นและตอนกลาง'
from unique_words source
where word.normalized_text = source.word;

with expanded as (
  select distinct skill_code, unnest(items) as word
  from book_vocabulary_source
), resolved_words as (
  select normalized_text, min(id::text)::uuid as id
  from public.words
  group by normalized_text
)
insert into public.word_skills (word_id, skill_id)
select word.id, skill.id
from expanded source
join resolved_words word on word.normalized_text = source.word
join public.skills skill on skill.code = source.skill_code
on conflict do nothing;
